 route 10.100.190.0/24 next-hop 10.100.100.2;
 route 10.100.191.0/24 next-hop 10.100.100.2;
 }
 rib-groups {
 STAGING-RIB {
 import-rib [ inet.0 PATH-1.inet.0 ];
 }
 }
 router-id 10.100.254.1;
}
firewall {
 family inet {
 filter FBF-TEST {
 term TERM-1 {
 from {
